"""Generated operation catalog from the supplied ConnectSecure OpenAPI 3.0 specification."""

from __future__ import annotations

import base64
import json
from dataclasses import dataclass


@dataclass(frozen=True)
class Operation:
    name: str
    method: str
    path: str
    summary: str
    has_body: bool = False


_ENCODED_OPERATIONS = ""
OPERATIONS: tuple[Operation, ...] = tuple(
    Operation(*row) for row in json.loads(base64.b64decode(_ENCODED_OPERATIONS))
)

